<script setup>
import { storeModule as wayfinderStoreModule1, storeLesson as wayfinderStoreLesson2, index as wayfinderIndex3, update as wayfinderUpdate5 } from './../../../actions/App/Http/Controllers/Staff/AdminCourseController';
import { course as wayfinderCourse4 } from './../../../actions/App/Http/Controllers/PublicController';

import { Link, router, useForm } from '@inertiajs/vue3';
import StaffAdminLayout from '../../../Layouts/StaffAdminLayout.vue';

const props = defineProps({ course: Object, categories: Array, mentors: Array });
const details = useForm({ title: props.course.title, slug: props.course.slug, category_id: props.course.category_id || '', mentor_ids: props.course.mentors.map((mentor) => mentor.id), subtitle: props.course.subtitle || '', description: props.course.description || '', level: props.course.level, duration_weeks: props.course.duration_weeks, price: (props.course.price_minor / 100).toFixed(2), currency: props.course.currency, cover_image: props.course.cover_image || '', cover_upload: null, status: props.course.status });
const moduleForm = useForm({ title: '', description: '' });
const lessonForm = useForm({ title: '', summary: '', type: 'live', duration_seconds: 0, video_url: '', body: '', is_preview: false });
function addModule() { moduleForm.post(wayfinderStoreModule1.url({ course: props.course.id }), { onSuccess: () => moduleForm.reset() }); }
function addLesson(moduleId) { lessonForm.post(wayfinderStoreLesson2.url({ course: props.course.id, module: moduleId }), { onSuccess: () => lessonForm.reset() }); }
function remove(url, message) { if (window.confirm(message)) router.delete(url); }
</script>

<template>
  <StaffAdminLayout><div class="admin-heading"><div><Link :href="wayfinderIndex3().url" class="admin-back">← All courses</Link><div class="eyebrow">COURSE EDITOR · {{ course.status.toUpperCase() }}</div><h1>{{ course.title }}</h1><p>Update public course information and manage its curriculum. Published changes appear in course discovery.</p></div><Link :href="wayfinderCourse4.url({ slug: course.slug })" target="_blank" class="button button-dark">Preview public page <UiIcon name="arrow-up-right" :size="13"/></Link></div>
    <section class="admin-panel"><h2>Course details</h2><form class="admin-form" @submit.prevent="details.put(wayfinderUpdate5.url({ course: course.id }))"><div class="admin-form-grid"><label>Title<input v-model="details.title" required><small class="admin-form-error">{{ details.errors.title }}</small></label><label>URL slug<input v-model="details.slug" required><small class="admin-form-error">{{ details.errors.slug }}</small></label></div><div class="admin-form-grid"><label>Category<select v-model="details.category_id"><option value="">Uncategorized</option><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Level<select v-model="details.level"><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="all_levels">All levels</option></select></label></div><label>Mentor(s)<select v-model="details.mentor_ids" multiple size="3"><option v-for="mentor in mentors" :key="mentor.id" :value="mentor.id">{{ mentor.name }}</option></select><small>Teachers and administrators can be assigned as mentors.</small></label><label>Subtitle<input v-model="details.subtitle"></label><label>Description<textarea v-model="details.description" rows="5"></textarea></label><div class="admin-form-grid"><label>Duration in weeks<input v-model.number="details.duration_weeks" type="number" min="1"></label><label>Price<input v-model.number="details.price" type="number" min="0" step="0.01"></label></div><div class="admin-form-grid"><label>Currency<input v-model="details.currency" maxlength="3"></label><label>Replace cover image<input type="file" accept="image/jpeg,image/png,image/webp" @input="details.cover_upload = $event.target.files[0] || null"><small>Current image is kept unless a new file is selected.</small><small class="admin-form-error">{{ details.errors.cover_upload }}</small></label></div><label>Status<select v-model="details.status"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></label><div class="admin-form-actions"><button class="button button-dark" :disabled="details.processing">Save course</button></div></form></section>
    <section class="admin-panel curriculum-panel"><div class="admin-section-heading"><div><div class="eyebrow">PUBLIC CURRICULUM</div><h2>Modules & lessons</h2></div><span class="admin-chip">{{ course.modules.length }} modules</span></div><article v-for="module in course.modules" :key="module.id" class="curriculum-module"><div class="admin-section-heading"><div><h3>{{ module.position.toString().padStart(2, '0') }} · {{ module.title }}</h3><p>{{ module.description }}</p></div><button class="admin-danger" type="button" @click="remove(`/staff/manage/courses/${course.id}/modules/${module.id}`, 'Delete this module and all lessons in it?')">Delete module</button></div><div v-for="lesson in module.lessons" :key="lesson.id" class="lesson-row"><span><UiIcon :name="lesson.type === 'live' ? 'users' : lesson.type === 'video' ? 'play' : 'file-text'" :size="14"/><b>{{ lesson.title }}</b><small>{{ lesson.type }}<template v-if="lesson.is_preview"> · public preview</template></small></span><button class="admin-danger" type="button" @click="remove(`/staff/manage/courses/${course.id}/modules/${module.id}/lessons/${lesson.id}`, 'Remove this curriculum item?')">Remove</button></div><form class="admin-form lesson-form" @submit.prevent="addLesson(module.id)"><div class="admin-form-grid"><label>Lesson title<input v-model="lessonForm.title" required></label><label>Type<select v-model="lessonForm.type"><option value="live">Live class</option><option value="video">Video lesson</option><option value="reading">Reading</option><option value="assignment">Assignment</option></select></label></div><div class="admin-form-grid"><label>Short summary<input v-model="lessonForm.summary"></label><label v-if="lessonForm.type === 'video'">Video URL<input v-model="lessonForm.video_url" type="url"></label><label v-else>Duration in seconds<input v-model.number="lessonForm.duration_seconds" type="number" min="0"></label></div><label v-if="lessonForm.type === 'reading'">Lesson text<textarea v-model="lessonForm.body" rows="3"></textarea></label><label class="checkbox-label"><input v-model="lessonForm.is_preview" type="checkbox"> Make this item available as a public preview</label><div class="admin-form-actions"><button class="button button-dark" :disabled="lessonForm.processing">Add lesson</button></div></form></article><div v-if="!course.modules.length" class="admin-empty">Add the first module to give this course a clear learning path.</div><form class="admin-form add-module" @submit.prevent="addModule"><h3>Add a module</h3><div class="admin-form-grid"><label>Module title<input v-model="moduleForm.title" required></label><label>Description<input v-model="moduleForm.description"></label></div><div class="admin-form-actions"><button class="button button-dark" :disabled="moduleForm.processing">Add module</button></div></form></section>
  </StaffAdminLayout>
</template>

<style scoped>.admin-back{display:inline-block;color:#5b7051;font-size:12px;margin-bottom:12px}.admin-heading>a{white-space:nowrap}.admin-section-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.admin-section-heading h2{margin-bottom:0}.admin-section-heading h3,.add-module h3{font:400 1.15rem var(--serif,Georgia,serif);margin:0}.admin-section-heading p{font-size:12px;color:#7c8279;margin:6px 0}.curriculum-module{border-top:1px solid #e9e8e2;margin-top:19px;padding-top:18px}.lesson-row{display:flex;justify-content:space-between;align-items:center;padding:11px;background:#f8f8f4;border-radius:6px;margin-top:8px}.lesson-row>span{display:flex;gap:10px;align-items:center}.lesson-row small{color:#737a70;text-transform:capitalize}.admin-danger{border:0;background:transparent;color:#a04b44;font-size:11px;cursor:pointer}.lesson-form{background:#fafaf7;padding:15px;border-radius:7px;margin-top:12px}.checkbox-label{display:flex!important;align-items:center;gap:9px!important}.checkbox-label input{width:auto}.add-module{border-top:1px solid #e9e8e2;margin-top:24px;padding-top:20px}@media(max-width:750px){.admin-heading{align-items:flex-start}.admin-heading>a{white-space:normal}.lesson-row>span{flex-wrap:wrap}}</style>
